const corsHeaders = {
  "Content-Type": "application/json; charset=utf-8",
  "Cache-Control": "no-store",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "no-referrer"
};

function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: corsHeaders });
}
function b64(bytes) {
  let binary = "";
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}
function fromB64(text) {
  let s = text.replace(/-/g, "+").replace(/_/g, "/");
  while (s.length % 4) s += "=";
  return Uint8Array.from(atob(s), c => c.charCodeAt(0));
}
async function sign(value, secret) {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return b64(new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(value))));
}

// Senhas de categoria: PBKDF2 com sal ("v2$sal$hash"). Categorias antigas (SHA-256 puro) continuam funcionando
// até a senha ser trocada.
async function pbkdf2(password, salt) {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: "PBKDF2", salt, iterations: 100000, hash: "SHA-256" }, key, 256));
}
async function hashPassword(password) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  return "v2$" + b64(salt) + "$" + b64(await pbkdf2(password, salt));
}
async function checkPassword(password, stored) {
  if (!stored) return false;
  if (stored.startsWith("v2$")) {
    const [, salt, hash] = stored.split("$");
    return safeEqual(b64(await pbkdf2(password, fromB64(salt))), hash);
  }
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(password));
  return safeEqual(b64(new Uint8Array(digest)), stored);
}
// O token de acesso fica preso à senha atual: trocar a senha da categoria invalida os acessos anteriores.
function tokenPayload(cat, expires) { return cat.id + "." + expires + "." + String(cat.passwordHash || "").slice(-16); }
async function categoryToken(cat, env) {
  const expires = String(Date.now() + 4 * 60 * 60 * 1000);
  return expires + "." + await sign(tokenPayload(cat, expires), env.ADMIN_PASSWORD);
}
async function validCategoryToken(token, cat, env) {
  if (!token || !cat || !env.ADMIN_PASSWORD) return false;
  const [expires, signature] = token.split(".");
  if (!expires || !signature || Number(expires) < Date.now()) return false;
  return safeEqual(signature, await sign(tokenPayload(cat, expires), env.ADMIN_PASSWORD));
}
async function sessionValid(request, env) {
  if (!env.ADMIN_PASSWORD) return false;
  const cookie = request.headers.get("Cookie") || "";
  const token = cookie.split(";").map(x => x.trim()).find(x => x.startsWith("fv_admin="))?.slice(9);
  if (!token) return false;
  const [expires, signature] = token.split(".");
  if (!expires || !signature || Number(expires) < Date.now()) return false;
  return safeEqual(signature, await sign(expires, env.ADMIN_PASSWORD));
}
async function safeEqual(a, b) {
  const enc = new TextEncoder();
  const [x, y] = await Promise.all([crypto.subtle.digest("SHA-256", enc.encode(String(a))), crypto.subtle.digest("SHA-256", enc.encode(String(b)))]);
  const xa = new Uint8Array(x), ya = new Uint8Array(y);
  let diff = 0;
  for (let i = 0; i < xa.length; i++) diff |= xa[i] ^ ya[i];
  return diff === 0;
}
function cookie(value, maxAge) {
  return "fv_admin=" + value + "; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=" + maxAge;
}
async function readJson(request, max = 20000) {
  const text = await request.text();
  if (text.length > max) throw new Error("Corpo da solicitação muito grande.");
  return JSON.parse(text);
}

const FILE_KEY = /^[a-z0-9-]+\/[a-zA-Z0-9._-]+\.(png|gif|svg)$/i;
const fileType = key => /\.svg$/i.test(key) ? "image/svg+xml" : /\.gif$/i.test(key) ? "image/gif" : "image/png";
const MAX_SVG_BYTES = 1024 * 1024;

// SVG pode carregar código. Aceitamos só desenho vetorial "puro": sem scripts, eventos, objetos externos
// nem referências a outros sites. Qualquer coisa suspeita faz o arquivo ser recusado (não "consertamos" em silêncio).
function checkSvg(bytes) {
  if (bytes.length > MAX_SVG_BYTES) return { error: "Cada SVG deve ter no máximo 1 MB. SVG vetorial costuma pesar bem menos." };
  let text;
  try { text = new TextDecoder("utf-8", { fatal: true }).decode(bytes); } catch { return { error: "O SVG precisa estar em UTF-8." }; }
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
  if (!/^\s*(?:<\?xml[\s\S]*?\?>\s*|<!--[\s\S]*?-->\s*|<!DOCTYPE\s[^\[>]*>\s*)*<svg[\s>]/i.test(text)) return { error: "Arquivo SVG inválido." };
  if (/<!ENTITY/i.test(text)) return { error: "SVG com ENTITY não é aceito. No Illustrator, exporte em SVG 1.1 com 'Atributos de apresentação'." };
  if (/<\s*(script|foreignObject|iframe|embed|object|audio|video|animate|set|handler|listener)\b/i.test(text)) return { error: "SVG com script, animação ou conteúdo externo não é aceito." };
  if (/[\s"'\/;]on[a-z]+\s*=/i.test(text) || /javascript:/i.test(text) || /@import/i.test(text)) return { error: "SVG com código não é aceito." };
  for (const m of text.matchAll(/\bhref\s*=\s*(["'])(.*?)\1/gi)) {
    if (!(m[2].startsWith("#") || /^data:image\/(png|jpe?g|gif|webp);base64,/i.test(m[2]))) return { error: "SVG com link para fora não é aceito." };
  }
  if (/url\(\s*["']?\s*(?!#|data:image)/i.test(text)) return { error: "SVG com referência externa não é aceito." };
  // Garante width/height (Illustrator costuma exportar só viewBox; sem tamanho alguns navegadores não desenham no canvas)
  const tag = text.match(/<svg\b[^>]*>/i)[0];
  const has = n => new RegExp("\\s" + n + "\\s*=", "i").test(tag);
  if (!(has("width") && has("height"))) {
    const vb = tag.match(/\sviewBox\s*=\s*["']\s*(-?[\d.eE+-]+)[\s,]+(-?[\d.eE+-]+)[\s,]+(-?[\d.eE+-]+)[\s,]+(-?[\d.eE+-]+)\s*["']/i);
    const w = vb && parseFloat(vb[3]), h = vb && parseFloat(vb[4]);
    if (!(w > 0 && h > 0)) return { error: "SVG sem viewBox nem tamanho (width/height)." };
    const add = (has("width") ? "" : ' width="' + w + '"') + (has("height") ? "" : ' height="' + h + '"');
    const fixed = tag.replace(/<svg\b/i, () => "<svg" + add);
    text = text.replace(tag, () => fixed);
  }
  return { bytes: new TextEncoder().encode(text) };
}
const isEnabled = cat => cat.enabled !== false;
const publicCategory = ({ passwordHash, ...cat }) => ({ ...cat, enabled: isEnabled(cat) });
function cleanName(value) { return String(value || "").trim().replace(/\s+/g, " ").slice(0, 48); }

async function listItems(env, cat, accessToken = "") {
  const items = [];
  let cursor;
  do {
    const page = await env.STICKERS_FILES.list({ prefix: cat.id + "/", cursor, limit: 1000, include: ["customMetadata"] });
    const entries = await Promise.all(page.objects.map(async obj => {
      let storedName = obj.customMetadata?.originalName;
      if (!storedName) { const details = await env.STICKERS_FILES.head(obj.key); storedName = details?.customMetadata?.originalName; }
      const fallbackName = obj.key.split("/").pop().replace(/^[0-9a-f-]{36}-/i, "").replace(/_/g, " ");
      return { key: obj.key, name: storedName || fallbackName, category: cat.id, url: "/api/library/file?key=" + encodeURIComponent(obj.key) + (accessToken ? "&token=" + encodeURIComponent(accessToken) : "") };
    }));
    items.push(...entries);
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  items.sort((a, b) => a.name.localeCompare(b.name, "pt", { numeric: true }));
  return items;
}
const escRe = t => t.replace(/[.*+?^$|()[\]{}\\]/g, "\\$&");
const numberRe = cat => new RegExp("^" + escRe(cat.name) + " (\\d+)\\.(png|gif|svg)$", "i");
async function listObjs(env, cat) {
  const out = [];
  let cursor;
  do {
    const page = await env.STICKERS_FILES.list({ prefix: cat.id + "/", cursor, limit: 1000, include: ["customMetadata"] });
    for (const o of page.objects) out.push({ key: o.key, uploaded: +new Date(o.uploaded), name: o.customMetadata?.originalName || "" });
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  return out;
}
// próximo número livre para "<Categoria> N.ext"
async function nextNumber(env, cat) {
  const re = numberRe(cat);
  let max = 0;
  for (const o of await listObjs(env, cat)) { const m = re.exec(o.name); if (m) max = Math.max(max, +m[1]); }
  return max + 1;
}
async function countItems(env, cat) {
  let count = 0, cursor;
  do {
    const page = await env.STICKERS_FILES.list({ prefix: cat.id + "/", cursor, limit: 1000 });
    count += page.objects.length;
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  return count;
}

async function handle(request, env) {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/api/")) {
      if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: { ...corsHeaders, "Access-Control-Allow-Methods": "GET,POST,PATCH,DELETE,OPTIONS", "Access-Control-Allow-Headers": "Content-Type" } });
      if (url.pathname === "/api/health" && request.method === "GET") return json({ ok: true, adminConfigured: !!env.ADMIN_PASSWORD });
      if (url.pathname === "/api/admin/login" && request.method === "POST") {
        if (!env.ADMIN_PASSWORD) return json({ error: "Configure ADMIN_PASSWORD como secret do Worker." }, 503);
        const body = await readJson(request, 2000);
        if (typeof body.password !== "string" || !(await safeEqual(body.password, env.ADMIN_PASSWORD))) return json({ error: "Senha incorreta." }, 401);
        const expires = String(Date.now() + 8 * 60 * 60 * 1000);
        const signature = await sign(expires, env.ADMIN_PASSWORD);
        return new Response(JSON.stringify({ ok: true }), { headers: { ...corsHeaders, "Set-Cookie": cookie(expires + "." + signature, 8 * 60 * 60) } });
      }
      if (url.pathname === "/api/admin/logout" && request.method === "POST") return new Response(JSON.stringify({ ok: true }), { headers: { ...corsHeaders, "Set-Cookie": cookie("", 0) } });
      if (url.pathname === "/api/admin/session" && request.method === "GET") return json({ ok: await sessionValid(request, env) });
      if (url.pathname === "/api/library/access" && request.method === "POST") {
        if (!env.STICKERS) return json({ error: "Biblioteca ainda não configurada." }, 503);
        const body = await readJson(request, 2000), category = String(body.category || ""), password = String(body.password || "");
        const categories = JSON.parse(await env.STICKERS.get("library_categories") || "[]"), cat = categories.find(c => c.id === category && c.protected && isEnabled(c));
        if (!cat || !(await checkPassword(password, cat.passwordHash))) return json({ error: "Senha incorreta." }, 401);
        return json({ ok: true, token: await categoryToken(cat, env) });
      }
      if (url.pathname === "/api/library" && request.method === "GET") {
        if (!env.STICKERS_FILES || !env.STICKERS) return json({ error: "Biblioteca ainda não configurada." }, 503);
        const all = JSON.parse(await env.STICKERS.get("library_categories") || "[]");
        const isAdmin = await sessionValid(request, env);
        // Categorias desativadas ficam invisíveis para o público (mas continuam guardadas).
        const visible = isAdmin && url.searchParams.get("scope") === "admin" ? all : all.filter(isEnabled);
        if (url.searchParams.get("view") === "categories") return json({ categories: visible.map(publicCategory) });
        const category = url.searchParams.get("category") || "";
        if (category && !visible.some(c => c.id === category)) return json({ error: "Categoria indisponível." }, 404);
        const selected = category ? visible.filter(c => c.id === category) : visible;
        const accessToken = url.searchParams.get("token") || "";
        if (category && selected[0]?.protected && !isAdmin && !(await validCategoryToken(accessToken, selected[0], env))) return json({ error: "Acesso não autorizado." }, 401);
        const items = [];
        for (const cat of selected) {
          if (!category && cat.protected && !isAdmin) continue;
          items.push(...await listItems(env, cat, accessToken));
        }
        return json({ categories: visible.map(publicCategory), items });
      }
      if (url.pathname === "/api/library/file" && request.method === "GET") {
        if (!env.STICKERS_FILES || !env.STICKERS) return json({ error: "Biblioteca não configurada." }, 503);
        const key = url.searchParams.get("key") || "";
        if (!FILE_KEY.test(key)) return json({ error: "Arquivo inválido." }, 400);
        const categoryId = key.split("/")[0], categories = JSON.parse(await env.STICKERS.get("library_categories") || "[]"), cat = categories.find(c => c.id === categoryId);
        const isAdmin = await sessionValid(request, env);
        if (cat && !isEnabled(cat) && !isAdmin) return json({ error: "Arquivo não encontrado." }, 404);
        const protectedCategory = !!cat?.protected;
        if (protectedCategory && !isAdmin && !(await validCategoryToken(url.searchParams.get("token") || "", cat, env))) return json({ error: "Acesso não autorizado." }, 401);
        const object = await env.STICKERS_FILES.get(key);
        if (!object) return json({ error: "Arquivo não encontrado." }, 404);
        const headers = new Headers({ "Content-Type": fileType(key), "X-Content-Type-Options": "nosniff" });
        object.writeHttpMetadata(headers);
        headers.set("Content-Type", fileType(key));
        if (/\.svg$/i.test(key)) headers.set("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; img-src data:; sandbox");
        headers.set("Cache-Control", protectedCategory || (cat && !isEnabled(cat)) ? "private, max-age=3600" : "public, max-age=3600");
        return new Response(object.body, { headers });
      }
      if (url.pathname.startsWith("/api/admin/library/")) {
        if (!(await sessionValid(request, env))) return json({ error: "Acesso não autorizado." }, 401);
        if (!env.STICKERS_FILES || !env.STICKERS) return json({ error: "Vincule STICKERS_FILES e STICKERS ao Worker." }, 503);
        const getCategories = async () => JSON.parse(await env.STICKERS.get("library_categories") || "[]");
        const saveCategories = categories => env.STICKERS.put("library_categories", JSON.stringify(categories));
        const validPassword = password => password.length >= 3 && password.length <= 64;

        if (url.pathname === "/api/admin/library/overview" && request.method === "GET") {
          const categories = await getCategories();
          const counts = await Promise.all(categories.map(c => countItems(env, c)));
          return json({ categories: categories.map((c, i) => ({ ...publicCategory(c), count: counts[i] })) });
        }
        if (url.pathname === "/api/admin/library/items" && request.method === "GET") {
          const cat = (await getCategories()).find(c => c.id === url.searchParams.get("category"));
          if (!cat) return json({ error: "Categoria não encontrada." }, 404);
          return json({ items: await listItems(env, cat) });
        }
        if (url.pathname === "/api/admin/library/category" && request.method === "POST") {
          const body = await readJson(request, 2000), name = cleanName(body.name);
          if (!name) return json({ error: "Informe o nome da categoria." }, 400);
          const categories = await getCategories();
          if (categories.some(c => c.name.toLowerCase() === name.toLowerCase())) return json({ error: "Esta categoria já existe." }, 409);
          const slug = name.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "categoria";
          const id = slug + "-" + crypto.randomUUID().slice(0, 6);
          const password = String(body.password || "");
          if (password && !validPassword(password)) return json({ error: "A senha deve ter entre 3 e 64 caracteres." }, 400);
          categories.push({ id, name, enabled: true, ...(password ? { protected: true, passwordHash: await hashPassword(password) } : {}) });
          await saveCategories(categories);
          return json({ ok: true, id, categories: categories.map(publicCategory) });
        }
        if (url.pathname === "/api/admin/library/category" && request.method === "PATCH") {
          const body = await readJson(request, 2000), id = String(body.id || "");
          const categories = await getCategories(), cat = categories.find(c => c.id === id);
          if (!cat) return json({ error: "Categoria não encontrada." }, 404);
          if (body.name !== undefined) {
            const name = cleanName(body.name);
            if (!name) return json({ error: "Informe o nome da categoria." }, 400);
            if (categories.some(c => c.id !== id && c.name.toLowerCase() === name.toLowerCase())) return json({ error: "Já existe uma categoria com esse nome." }, 409);
            cat.name = name;
          }
          if (body.enabled !== undefined) {
            if (typeof body.enabled !== "boolean") return json({ error: "Valor inválido." }, 400);
            cat.enabled = body.enabled;
          }
          if (body.removePassword === true) {
            delete cat.passwordHash;
            delete cat.protected;
          } else if (body.password !== undefined) {
            const password = String(body.password);
            if (!validPassword(password)) return json({ error: "A senha deve ter entre 3 e 64 caracteres." }, 400);
            cat.passwordHash = await hashPassword(password);
            cat.protected = true;
          }
          await saveCategories(categories);
          return json({ ok: true, category: publicCategory(cat) });
        }
        if (url.pathname === "/api/admin/library/order" && request.method === "POST") {
          const body = await readJson(request, 12000), ids = body.ids;
          const categories = await getCategories();
          if (!Array.isArray(ids) || ids.length !== categories.length || new Set(ids).size !== categories.length || ids.some(id => typeof id !== "string" || !categories.some(c => c.id === id))) return json({ error: "A ordem enviada é inválida." }, 400);
          const byId = new Map(categories.map(c => [c.id, c]));
          const reordered = ids.map(id => byId.get(id));
          await saveCategories(reordered);
          return json({ ok: true, categories: reordered.map(publicCategory) });
        }
        if (url.pathname === "/api/admin/library/upload" && request.method === "POST") {
          const form = await request.formData(), category = String(form.get("category") || ""), files = form.getAll("files");
          const categories = await getCategories();
          const upCat = categories.find(c => c.id === category);
          if (!upCat) return json({ error: "Categoria inválida." }, 400);
          let nextNum = await nextNumber(env, upCat);
          if (!files.length || files.length > 30) return json({ error: "Envie de 1 a 30 arquivos por vez." }, 400);
          const uploaded = [];
          for (const file of files) {
            if (!file || typeof file.arrayBuffer !== "function") continue;
            if (file.size > 8 * 1024 * 1024) return json({ error: "Cada arquivo deve ter no máximo 8 MB (SVG: 1 MB)." }, 413);
            let bytes = new Uint8Array(await file.arrayBuffer());
            const isPng = bytes.length >= 8 && bytes[0] === 137 && bytes[1] === 80 && bytes[2] === 78 && bytes[3] === 71 && bytes[4] === 13 && bytes[5] === 10 && bytes[6] === 26 && bytes[7] === 10;
            const isGif = bytes.length >= 6 && bytes[0] === 71 && bytes[1] === 73 && bytes[2] === 70 && bytes[3] === 56 && (bytes[4] === 55 || bytes[4] === 57) && bytes[5] === 97;
            let ext = isGif ? "gif" : "png";
            if (!isPng && !isGif) {
              const svg = checkSvg(bytes);
              if (svg.error) return json({ error: (file.name ? file.name + ": " : "") + (/<svg/i.test(new TextDecoder().decode(bytes.slice(0, 2000))) ? svg.error : "Todos os arquivos precisam ser PNG, GIF ou SVG válidos.") }, 400);
              bytes = svg.bytes; ext = "svg";
            }
            const originalName = upCat.name + " " + (nextNum++) + "." + ext;
            const safeName = originalName.replace(/[^a-zA-Z0-9._-]/g, "_").replace(/\.(png|gif|svg)$/i, "").slice(0, 80) || "stickers";
            const key = category + "/" + crypto.randomUUID() + "-" + safeName + "." + ext;
            await env.STICKERS_FILES.put(key, bytes, { httpMetadata: { contentType: ext === "svg" ? "image/svg+xml" : "image/" + ext }, customMetadata: { originalName } });
            uploaded.push(key);
          }
          return json({ ok: true, uploaded: uploaded.length, message: uploaded.length + " arquivo(s) enviado(s)." });
        }
        if (url.pathname === "/api/admin/library/file" && request.method === "DELETE") {
          const body = await readJson(request, 2000), key = String(body.key || "");
          if (!FILE_KEY.test(key)) return json({ error: "Arquivo inválido." }, 400);
          await env.STICKERS_FILES.delete(key);
          return json({ ok: true });
        }
        if (url.pathname === "/api/admin/library/renumber" && request.method === "POST") {
          const body = await readJson(request, 2000), rCat = (await getCategories()).find(c => c.id === String(body.category || ""));
          if (!rCat) return json({ error: "Categoria não encontrada." }, 404);
          const re = numberRe(rCat), objs = await listObjs(env, rCat);
          let max = 0;
          for (const o of objs) { const m = re.exec(o.name); if (m) max = Math.max(max, +m[1]); }
          const todo = objs.filter(o => !re.test(o.name)).sort((a, b) => a.uploaded - b.uploaded || a.key.localeCompare(b.key));
          const batch = todo.slice(0, 20);
          for (const o of batch) {
            const src = await env.STICKERS_FILES.get(o.key);
            if (!src) continue;
            await env.STICKERS_FILES.put(o.key, await src.arrayBuffer(), { httpMetadata: { contentType: fileType(o.key) }, customMetadata: { ...(src.customMetadata || {}), originalName: rCat.name + " " + (++max) + "." + o.key.split(".").pop().toLowerCase() } });
          }
          return json({ ok: true, changed: batch.length, remaining: todo.length - batch.length });
        }
        if (url.pathname === "/api/admin/library/clone" && request.method === "POST") {
          const body = await readJson(request, 2000), key = String(body.key || ""), target = String(body.category || "");
          if (!FILE_KEY.test(key)) return json({ error: "Arquivo inválido." }, 400);
          const targetCat = (await getCategories()).find(c => c.id === target);
          if (!targetCat) return json({ error: "Categoria de destino inválida." }, 400);
          if (key.split("/")[0] === target) return json({ error: "O sticker já está nessa categoria." }, 400);
          const src = await env.STICKERS_FILES.get(key);
          if (!src) return json({ error: "Sticker não encontrado." }, 404);
          const cloneName = targetCat.name + " " + (await nextNumber(env, targetCat)) + "." + key.split(".").pop().toLowerCase();
          const newKey = target + "/" + crypto.randomUUID() + "-" + cloneName.replace(/[^a-zA-Z0-9._-]/g, "_");
          await env.STICKERS_FILES.put(newKey, await src.arrayBuffer(), { httpMetadata: { contentType: fileType(key) }, customMetadata: { originalName: cloneName } });
          return json({ ok: true, key: newKey });
        }
        if (url.pathname === "/api/admin/library/category" && request.method === "DELETE") {
          const body = await readJson(request, 2000), id = String(body.id || "");
          const categories = await getCategories();
          if (!categories.some(c => c.id === id)) return json({ error: "Categoria não encontrada." }, 404);
          let cursor;
          do {
            const page = await env.STICKERS_FILES.list({ prefix: id + "/", cursor, limit: 1000 });
            if (page.objects.length) await env.STICKERS_FILES.delete(page.objects.map(o => o.key));
            cursor = page.truncated ? page.cursor : undefined;
          } while (cursor);
          await saveCategories(categories.filter(c => c.id !== id));
          return json({ ok: true });
        }
        return json({ error: "Endpoint administrativo não encontrado." }, 404);
      }

      return json({ error: "Endpoint não encontrado." }, 404);
    }
    return new Response(APP_HTML, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" } });
}

export default {
  async fetch(request, env) {
    try {
      return await handle(request, env);
    } catch (error) {
      const message = String(error?.message || "");
      if (error instanceof SyntaxError) return json({ error: "Solicitação inválida." }, 400);
      if (/muito grande/i.test(message)) return json({ error: message }, 413);
      return json({ error: "Erro interno do servidor. Tente novamente." }, 500);
    }
  }
};
